std::array<std::shared_mutex, 64> stripes;

Value get(const Key& k) {
  auto& s = stripes[std::hash<Key>{}(k) % stripes.size()];
  std::shared_lock g(s);
  return state.at(k);
}

void put(const Key& k, Value v) {
  auto& s = stripes[std::hash<Key>{}(k) % stripes.size()];
  std::unique_lock g(s);
  state[k] = std::move(v);
}
